INSERT INTO indicators VALUES(1,'heart_rate','Heart Rate','Cardiovascular','bpm','Measure your pulse using the designated heart-rate sensor. Remain still while the reading is taken.','Heart-rate monitor','Rest before taking the measurement and follow the sensor instructions.','According to mission protocol');
INSERT INTO indicators VALUES(2,'systolic_bp','Systolic Blood Pressure','Cardiovascular','mmHg','Measure your blood pressure using the designated blood pressure monitor. Record the systolic (upper) value.','Approved blood pressure monitor','Follow the device instructions and remain still during the measurement.','According to mission protocol');
INSERT INTO indicators VALUES(3,'diastolic_bp','Diastolic Blood Pressure','Cardiovascular','mmHg','Record the diastolic (lower) value displayed by the blood pressure monitor.','Approved blood pressure monitor','Take this measurement together with systolic blood pressure.','According to mission protocol');
INSERT INTO indicators VALUES(4,'sleep_duration','Sleep Duration','Behavioral','hours','Record the total time you slept during the previous sleep period.','Sleep tracking system or manual input','Use the previous completed sleep period.','Daily');
INSERT INTO indicators VALUES(5,'body_temperature','Body Temperature','General Health','°C','Measure and record your body temperature using the designated thermometer.','Digital thermometer','Follow the thermometer instructions and use the same measurement method consistently.','Daily');
INSERT INTO indicators VALUES(6,'oxygen_saturation','Oxygen Saturation','General Health','%','Measure your blood oxygen saturation (SpO2) using the designated pulse oximeter.','Pulse oximeter','Remain still and follow the device instructions until a stable reading is displayed.','According to mission protocol');
INSERT INTO indicators VALUES(7,'respiratory_rate','Respiratory Rate','Respiratory','breaths/min','Measure the number of breaths taken per minute while resting.','Timer or respiratory monitoring sensor','Rest before measurement and breathe normally without deliberately changing your breathing.','Daily');
INSERT INTO indicators VALUES(8,'body_mass','Body Mass','General Health','kg','Measure and record your body mass using the designated spaceflight body-mass measurement device.','Spaceflight-compatible body-mass measurement device','Follow the device instructions and use the same measurement procedure consistently.','According to mission protocol');
INSERT INTO indicators VALUES(9,'sleep_quality','Sleep Quality','Behavioral','score_1_5','Rate the quality of your previous sleep period from 1 (very poor) to 5 (excellent).','Self-assessment','Consider how restful your sleep was and whether you experienced interruptions.','Daily');
INSERT INTO indicators VALUES(10,'mood','Mood','Behavioral','score_1_5','Rate your current mood from 1 (very negative) to 5 (very positive).','Self-assessment','Consider your current emotional state.','Daily');
INSERT INTO indicators VALUES(11,'fatigue','Fatigue','Behavioral','score_1_5','Rate your current level of fatigue from 1 (not fatigued) to 5 (extremely fatigued).','Self-assessment','Consider your current energy level and how physically or mentally tired you feel.','Daily');
INSERT INTO indicators VALUES(12,'exercise_duration','Exercise Duration','Musculoskeletal','minutes','Record the total number of minutes spent exercising during the reporting period.','Exercise equipment or activity tracking system','Use the completed exercise period.','Daily');
INSERT INTO indicators VALUES(13,'balance_performance','Balance Performance','Sensorimotor','score','Complete the designated standardized balance and coordination assessment. Record the resulting score.','Approved sensorimotor assessment equipment','Follow the assessment instructions and complete the test under standardized conditions.','According to mission protocol');
INSERT INTO indicators VALUES(14,'hydration_self_assessment','Hydration Self-Assessment','Nutrition','score_1_5','Rate your perceived hydration status using the standardized 1-5 assessment scale.','Self-assessment','Consider thirst and other relevant symptoms before answering.','Daily');
INSERT INTO indicators VALUES(15,'radiation_dose','Radiation Dose','Radiation','mSv','Record the effective radiation dose reported by the radiation monitoring system for the reporting interval.','Radiation monitoring system','Use the instrument reading and its documented reporting interval.','According to radiation monitoring protocol');
INSERT INTO indicators VALUES(16,'stress_level','Stress Level','Behavioral','score_1_5','Rate your perceived stress level from 1 (very low) to 5 (very high).','Self-assessment','Consider your current psychological state.','Daily');
INSERT INTO indicators VALUES(17,'reaction_time','Reaction Time','Sensorimotor','ms','Complete the standardized reaction-time test and record the average response time.','Computer-based reaction-time test','Follow the test instructions and complete the required trials.','According to mission protocol');
INSERT INTO indicators VALUES(18,'muscle_strength','Muscle Strength','Musculoskeletal','score','Complete the designated standardized strength assessment and record its result.','Approved strength-testing equipment','Follow the prescribed testing protocol.','According to mission protocol');
INSERT INTO indicators VALUES(19,'dietary_intake','Dietary Energy Intake','Nutrition','kcal/day','Record the estimated total dietary energy consumed during the reporting period.','Food tracking system','Include all food and beverages consumed.','Daily');
INSERT INTO indicators VALUES(20,'fluid_intake','Daily Fluid Intake','Nutrition','mL','Record the total volume of fluids consumed during the reporting period.','Graduated drinking containers or fluid tracking system','Include all recorded fluid consumption.','Daily');
INSERT INTO indicators VALUES(21,'exercise_adherence','Exercise Adherence','Musculoskeletal','%','Record the percentage of prescribed exercise completed during the reporting period.','Exercise tracking system and prescribed exercise plan','Compare completed exercise with the prescribed exercise plan.','Daily');
